#!/usr/bin/env python3
"""Build research/texts.jsonl (original Greek + own notes) from source-data/extracted_fakelos.json.
Only public-domain ancient Greek is written; no school-book translation or commentary."""
import json, re, pathlib, unicodedata
R = pathlib.Path(__file__).resolve().parent.parent
F = json.load(open(R / "source-data/extracted_fakelos.json"))
T = json.load(open(R / "source-data/extracted.json"))

def fix(s):
    s = s.replace("[...]", "[…]").replace("ἴσῳ γάρ ὑπερέχει", "ἴσῳ γὰρ ὑπερέχει")
    s = re.sub(r"\s*\[:[^\]]*\]", "", s)           # editorial gloss "[: την πόλιν]" (school-book addition)
    s = unicodedata.normalize("NFC", s)
    return re.sub(r"\s+", " ", s).strip()

