def main():
    out = []
    for fk, code, id_, title, work, ref, tb, exam, ideas, vocab, phen in ITEMS:
        g = fix(F[fk]["greek"])
        rec = {"id": id_, "code": code, "title_el": title, "work": work, "ref": ref,
               "textbook_unit": tb, "greek": g, "exam_use": exam,
               "ideas": ideas, "vocab": vocab, "phenomena": phen}
        if "[…]" in g: rec["has_omission_marker"] = True
        out.append(rec)
    # textbook-only continuation of Γ.10
    ext = T["PL13"]
    i = ext.find("Σκέψαι τοίνυν")
    for r in out:
        if r["id"] == "C10":
            r["extra_textbook_greek"] = ext[i:] if i >= 0 else ""
    (R / "texts.jsonl").write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in out) + "\n")
    print(len(out), "records,", sum(len(r["greek"].split()) for r in out), "words")

main()
